import { NextResponse } from "next/server";

const CONTINUE_PAGE = "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Return to Moneo</title>"
  + "<style>body{font:16px/1.5 system-ui,sans-serif;max-width:32rem;margin:15vh auto;padding:0 1rem;color:#222;background:#fff}@media (prefers-color-scheme:dark){body{color:#eee;background:#0f1011}}</style>"
  + "<body><h1>Continue in Moneo</h1><p>The result is now open in the Moneo app. You can close this browser tab.</p></body></html>";

/**
 * Where a sign-in that ran in the system browser (bank, Scalable, ChatGPT) ends. In Moneo Desktop the
 * result opens in the app window through its private return address, and the browser tab says so;
 * otherwise, or if the window cannot open it, the browser is redirected as before.
 */
export async function connectionReturn(base: string | URL, path: string) {
  const bridge = process.env.MONEO_DESKTOP_AUTH_RETURN;
  if (process.env.MONEO_DESKTOP === "1" && bridge) {
    try {
      const response = await fetch(bridge, { method: "POST", headers: { "x-moneo-return": path }, signal: AbortSignal.timeout(10_000) });
      if (response.ok) return new Response(CONTINUE_PAGE, {
        headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "content-security-policy": "default-src 'none'; style-src 'unsafe-inline'; frame-ancestors 'none'" },
      });
    } catch { /* fall back to showing the result in the browser */ }
  }
  return NextResponse.redirect(new URL(path, base), 303);
}

import { randomUUID } from "node:crypto";
import http from "node:http";
import type { AddressInfo } from "node:net";

// The only pages a sign-in may return to: the connection results on Import and Settings.
const RETURN_PATH = /^\/(import\?(bank|scalable)=(connected|error|invalid)(#scalable)?|settings\?chatgpt=[A-Za-z0-9%._~-]{1,600}#ai-access)$/;

/**
 * A loopback address, secret to this launch, that Moneo's server calls when a sign-in in the system
 * browser finishes, so the result opens in the app window. Browsers cannot reach it: they do not know
 * the address, and their cross-site POSTs carry an Origin header, which is refused.
 */
export async function startAuthReturn(onReturn: (path: string) => Promise<void>) {
  const token = randomUUID();
  const server = http.createServer(async (req, res) => {
    if (req.method !== "POST" || req.url !== `/${token}` || req.headers.origin) {
      res.writeHead(403).end(); return;
    }
    const path = req.headers["x-moneo-return"];
    if (typeof path !== "string" || !RETURN_PATH.test(path)) {
      res.writeHead(400).end(); return;
    }
    try { await onReturn(path); res.writeHead(204).end(); }
    catch { res.writeHead(503).end(); }
  });
  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", resolve);
  });
  return {
    url: `http://127.0.0.1:${(server.address() as AddressInfo).port}/${token}`,
    close: () => { server.close(); server.closeAllConnections(); },
  };
}

import { expect, it, vi } from "vitest";
import { startAuthReturn } from "./auth-return";

it("opens only Moneo's own connection results, and only when its server asks", async () => {
  const open = vi.fn(async () => {});
  const bridge = await startAuthReturn(open);
  const post = (path: string, headers: Record<string, string> = {}) => fetch(bridge.url, { method: "POST", headers: { "x-moneo-return": path, ...headers } });
  try {
    expect((await fetch(bridge.url)).status).toBe(403);
    expect((await fetch(`${bridge.url}x`, { method: "POST", headers: { "x-moneo-return": "/import?bank=connected" } })).status).toBe(403);
    expect((await post("/import?bank=connected", { origin: "https://example.com" })).status).toBe(403);
    for (const path of ["https://example.com", "//example.com/import?bank=connected", "/import?bank=connected&next=/x", "/settings?chatgpt=a b#ai-access"]) {
      expect((await post(path)).status).toBe(400);
    }
    expect(open).not.toHaveBeenCalled();
    expect((await post("/import?scalable=connected#scalable")).status).toBe(204);
    expect((await post("/settings?chatgpt=ChatGPT%20sign-in%20failed.#ai-access")).status).toBe(204);
    expect(open).toHaveBeenCalledWith("/import?scalable=connected#scalable");
    open.mockRejectedValueOnce(new Error("window closed"));
    expect((await post("/import?bank=connected")).status).toBe(503);
  } finally { bridge.close(); }
});

